# pslproj.py p: order of the subgroup of PSL(2,p) generated by the PSL-parts of D D^-1 for the C5-pair member
import sys
p = int(sys.argv[1]); M = [tuple(map(int, s.split())) for s in sys.argv[2:]]
def mul(x, y): return ((x[0]*y[0]+x[1]*y[2]) % p, (x[0]*y[1]+x[1]*y[3]) % p, (x[2]*y[0]+x[3]*y[2]) % p, (x[2]*y[1]+x[3]*y[3]) % p)
def nrm(x):
    if x[0] == 0 and x[1] == 0 and x[2] == 0 and x[3] == 0: return x
    for v in x:
        if v % p:
            if v % p > (p-1)//2: return tuple((-w) % p for w in x)
            return x
def inv(x): return (x[3], (-x[1]) % p, (-x[2]) % p, x[0])
x = M[0]; y = M[1]; z1 = M[2]; z2 = M[3]
gens = {nrm(x), nrm(mul(mul(z1, y), inv(z1))), nrm(mul(mul(z2, y), inv(z2))), nrm(mul(mul(z1, y), inv(z2))), nrm(mul(mul(z2, y), inv(z1)))}
I = (1, 0, 0, 1); S = {I}; fr = [I]
while fr:
    nf = []
    for a in fr:
        for g in gens:
            b = nrm(mul(a, g))
            if b not in S: S.add(b); nf.append(b)
    fr = nf
print("PSL-projection order", len(S), "of", p*(p*p-1)//2)
